const D = { density: .55, energy: .55, hue: 200, speed: 1, scale: 1, warp: .25, x: .5, y: .46, seed: 0, style: 'frost', act: 'cruise' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const TAU = 6.28318530718;
const cl = (v,a,b) => v<a?a:v>b?b:v;
const sty = P.style;
const hz = cl(P.y, .28, .72) * height;
const cx = cl(P.x, .05, .95) * width;
const groundH = Math.max(20, height - hz);
const yOf = t => hz + Math.pow(t, 1.7) * groundH;
const hwOf = t => width * (.045 + t * .95) * .5 * P.scale;
const NR = Math.round(9 + P.density * 32);
const NC = Math.round(6 + P.density * 16);
const H = P.hue;

S.tre = (S.tre||0)*.8 + (A.treble||0)*.2;
S.bass = (S.bass||0)*.8 + (A.bass||0)*.2;
const glow = (.4 + .6*P.energy) * (.55 + .55*K.intensity);
const kick = Math.min(1, K.pulse*(.5+.5*K.intensity) + S.bass*.6);

// real-time scroll (integrate seconds -> never re-phases)
if (S.pt == null || K.t < S.pt) S.pt = K.t;
let dt = K.t - S.pt; S.pt = K.t; dt = cl(dt, 0, .1);
let sp = P.speed * (.5 + .8*K.intensity);
if (P.act === 'pulse') sp *= 1 + 1.0*kick;
if (P.act === 'tide')  sp *= .35 + .95*(.5 + .5*Math.sin(K.t*.055 + K.section*.9));
S.scroll = (S.scroll||0) + dt*sp*.58;
const scroll = S.scroll;

// ---- cached structural base ----
const key = width+'x'+height+'|'+sty+'|'+Math.round(H)+'|'+P.seed+'|'+Math.round(P.density*8)+'|'+Math.round(P.y*24)+'|'+Math.round(P.scale*8);
if (!S.base || S.key !== key) {
  const g = S.base && S.base.width===width && S.base.height===height ? S.base : createGraphics(width, height);
  g.colorMode(HSB,360,100,100,100); g.clear(); g.noStroke();
  const STR = 56;
  // sky
  for (let i=0;i<STR;i++){ const f=i/STR, y=f*hz;
    let h,s,b;
    if (sty==='frost'){ h=(H+18); s=24-14*f; b=52+30*f; }
    else if (sty==='wireframe'){ h=H; s=60; b=6+7*f; }
    else if (sty==='aurora'){ h=H; s=55; b=4+8*f; }
    else { h=H-10; s=50-20*f; b=10+18*f; }   // glacier
    g.fill(h,cl(s,4,90),cl(b,3,88),100); g.rect(0,y,width,hz/STR+1);
  }
  // aurora curtains (static shells; animated copy added live)
  if (sty==='aurora'){ g.push(); g.blendMode(ADD);
    for(let b0=0;b0<3;b0++){ const bh=(H+100+b0*70)%360;
      for(let x=0;x<width;x+=6){ const yy=hz*(.25+.45*Math.sin(x*.008+b0*2+P.seed))*(.6);
        g.fill(bh,70,80,7); g.rect(x, yy, 6, hz*.5); } } g.pop(); }
  // ground plane
  for (let i=0;i<STR;i++){ const t=i/STR, y=yOf(t), y2=yOf((i+1)/STR);
    let h,s,b;
    if (sty==='frost'){ h=(H+8); s=16+8*t; b=cl(88-58*Math.pow(t,.7),24,90); }
    else if (sty==='wireframe'){ h=H; s=70; b=4+6*t; }
    else if (sty==='aurora'){ h=H; s=45-20*t; b=6+14*Math.pow(t,1.2); }
    else { h=H-12+18*t; s=40-14*t; b=cl(70-46*Math.pow(t,.8),14,80); }   // glacier
    g.fill(h,cl(s,3,90),b,100); g.rect(0,y,width,(y2-y)+1);
  }
  // static texture
  g.push();
  if (sty==='frost'){ // stippled frost crystals
    g.blendMode(ADD);
    for(let i=0;i<170;i++){ const t=.05+.95*fr(i*2), y=yOf(t), hw=hwOf(t);
      const x=cx+(fr(i*2+1)*2-1)*hw; g.fill(H+20,10,100,4+7*t); const r=1+t*3.2;
      g.ellipse(x,y,r,r); } }
  else if (sty==='glacier'){ // faceted low-poly shading over plane
    for(let ry=0;ry<9;ry++){ const t0=ry/9,t1=(ry+1)/9;
      for(let cxi=0;cxi<8;cxi++){ const u0=cxi/8,u1=(cxi+1)/8, sh=fr(ry*8+cxi);
        const y0=yOf(t0),y1=yOf(t1),hw0=hwOf(t0),hw1=hwOf(t1);
        g.fill(H-8+22*sh, 30, cl(40+50*sh-30*t0,12,86), 32);
        g.quad(cx-hw0+u0*2*hw0,y0, cx-hw0+u1*2*hw0,y0, cx-hw1+u1*2*hw1,y1, cx-hw1+u0*2*hw1,y1); } } }
  else if (sty==='wireframe'){ /* void — grid only, drawn live */ }
  else { /* aurora ground faint */ }
  g.pop();
  S.base = g; S.key = key;
}
image(S.base, 0, 0);

// ---- live animated aurora roll (real-time, aurora style) ----
if (sty==='aurora'){ push(); blendMode(ADD); noStroke();
  for(let b0=0;b0<3;b0++){ const bh=(H+90+b0*70)%360;
    for(let x=0;x<width;x+=7){ const ph=x*.01+b0*1.7+K.t*(.25+.1*b0);
      const yy=hz*(.18+.32*(.5+.5*Math.sin(ph)));
      const hgt=hz*(.35+.2*Math.sin(ph*1.7));
      fill(bh,70,92, (10+10*Math.sin(ph*2))*glow);
      rect(x, yy, 7, hgt); } }
  pop(); }

// ---- live grid ----
noFill();
const jag = (sty==='frost'||sty==='glacier');
for (let r=0; r<=NR; r++){
  let t = (r - (scroll%1)) / NR;
  if (t<=0 || t>1) continue;
  const y = yOf(t), hw = hwOf(t), near=t;
  let h,s,b,a,sw;
  if (sty==='wireframe'){ h=H; s=80; b=100; a=20+64*near; sw=.5+near*1.6; }
  else if (sty==='aurora'){ h=(H+130)%360; s=40; b=100; a=10+40*near; sw=.5+near*1.6; }
  else if (sty==='glacier'){ h=H+10; s=30; b=100; a=14+58*near; sw=.6+near*2.2; }
  else { h=H+16; s=22; b=100; a=16+60*near; sw=.6+near*2.4; } // frost
  stroke(h,s,b, a*(.6+.6*glow));
  strokeWeight(sw);
  if (sty==='wireframe'){ drawingContext.shadowBlur=(4+12*near)*glow; drawingContext.shadowColor=color(h,90,100,90).toString(); }
  if (jag){
    beginShape();
    const seg = 8;
    for(let k=0;k<=seg;k++){ const u=k/seg; const xx=cx-hw+u*2*hw;
      const jj=(fr(r*13+k)*2-1)*hw*.05*(1-t)*4;
      vertex(xx, y+jj); }
    endShape();
  } else { line(cx-hw, y, cx+hw, y); }
}
drawingContext.shadowBlur = 0;

// converging verticals
const warp = P.warp;
for (let c=0; c<=NC; c++){
  const u=c/NC, d=(u-.5);
  const xTop=cx + d*width*.03*P.scale;
  const xBot=cx + d*width*1.9*P.scale*(1+warp*1.2*d*d*4);
  let h,s,b,a,sw;
  if (sty==='wireframe'){ h=(H+40)%360; s=80; b=100; a=44; sw=1.1; }
  else if (sty==='aurora'){ h=(H+130)%360; s=35; b=95; a=22; sw=.9; }
  else { h=H+14; s=20; b=100; a=28; sw=1.0; }
  stroke(h,s,b, a*(.6+.5*glow)); strokeWeight(sw);
  if (sty==='wireframe'){ drawingContext.shadowBlur=6*glow; drawingContext.shadowColor=color(h,90,100,80).toString(); }
  line(xTop, hz, xBot, height);
}
drawingContext.shadowBlur = 0;

// drifting snow / frost motes (continuous)
const NP = Math.round(P.density * 70);
push(); blendMode(ADD); noStroke();
for (let i=0;i<NP;i++){
  const lane=fr(i*4), spd=.4+fr(i*4+1)*1.0;
  let prog=(fr(i*4+2)+scroll*.12*spd)%1;
  const t=1-prog; if(t<=.02) continue;
  const y=yOf(t), hw=hwOf(t);
  const x=cx+(lane*2-1)*hw*.97 + Math.sin(K.t*.5+i*1.3)*hw*.05;
  const sz=(1.3+5*t)*(1+.5*S.tre);
  const h = sty==='aurora'?(H+120)%360 : H+18;
  fill(h, sty==='wireframe'?70:14, 100, Math.min(42,(9+34*t)*(.5+.9*glow)));
  ellipse(x,y,sz,sz);
}
pop();

// horizon frost flare (partial, safe)
push(); blendMode(ADD); noStroke();
const flare=(kick*.6+K.swell*.3)*glow;
for(let i=0;i<5;i++){ const rr=(5-i)*groundH*.045*(1+flare);
  fill(H+14, 24, 96, 4+8*flare); rect(0, hz-rr*.4, width, rr); }
pop();

blendMode(BLEND);
drawingContext.shadowBlur = 0;
